import 'package:flutter/material.dart';
class EmptyState extends StatelessWidget { final bool filtered; const EmptyState({super.key, this.filtered = false}); @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(filtered ? Icons.search_off_rounded : Icons.task_alt_rounded, size: 86, color: Theme.of(context).colorScheme.primary.withValues(alpha: .6)), const SizedBox(height: 18), Text(filtered ? 'No matching tasks' : 'Your task list is clear', style: Theme.of(context).textTheme.titleLarge), const SizedBox(height: 8), Text(filtered ? 'Try changing your search or filters.' : 'Tap the + button to add your first task.', textAlign: TextAlign.center)]))); }
